package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.json.JsonMapper;
class FormalInvocationSendPreparationTest {
 final JsonMapper json=new JsonMapper();
 @Test void exactMessagesAndExplicitOptionsArePreserved()throws Exception{var definition=json.readTree("{\"provider\":\"deepseek\",\"model_id\":\"real-fixed-model\"}");var p=json.readTree("{\"max_output_tokens\":123,\"temperature\":0.2,\"reasoning_effort\":\"none\",\"stop\":[\"END\"]}");var input=json.readTree("{\"messages\":[{\"role\":\"user\",\"content\":\"实际固定输入\"}],\"tools\":[]}");var result=FormalInvocationSendPreparation.providerBody(definition,p,input);assertEquals(input.required("messages"),result.required("messages"));assertEquals(123,result.required("max_tokens").intValue());assertTrue(result.required("stream_options").required("include_usage").booleanValue());assertFalse(result.has("tools"));assertFalse(result.has("api_key"));assertEquals("real-fixed-model",result.required("model").textValue());}
 @Test void unsupportedProviderCannotBorrowDeepSeekMapping()throws Exception{assertThrows(TenantAccessException.class,()->FormalInvocationSendPreparation.providerBody(json.readTree("{\"provider\":\"other\"}"),json.createObjectNode(),json.createObjectNode()));}
 @Test void reasoningToolContinuationIsRejected()throws Exception{var d=json.readTree("{\"provider\":\"deepseek\",\"model_id\":\"fixed\"}");var p=json.readTree("{\"max_output_tokens\":1,\"temperature\":null,\"reasoning_effort\":\"high\",\"stop\":[]}");var input=json.readTree("{\"messages\":[],\"tools\":[{\"type\":\"function\"}]}");assertThrows(TenantAccessException.class,()->FormalInvocationSendPreparation.providerBody(d,p,input));}
}
